function renderRequest(){const tb=$('#requestTable'),empty=$('#requestEmpty');empty.classList.toggle('hidden',state.requests.length>0);tb.innerHTML=state.requests.map((x,i)=>`<tr class="border-b border-slate-900"><td class="px-2 py-3 font-bold">${escapeHtml(x.model)}</td><td>${escapeHtml(x.class)}</td><td>${fmt(x.inventory)}</td><td>${fmt(x.requested_qty)}</td><td class="font-bold ${statusClass(x.stock_status)}">${escapeHtml(x.stock_status)}</td><td>${ceilDoi(x.doi)}</td><td class="font-bold text-blue-400">${typeof x.new_doi==='number'?ceilDoi(x.new_doi):escapeHtml(x.new_doi)}</td><td class="max-w-[220px] truncate pr-2">${escapeHtml(x.remarks||'—')}</td><td><button class="removeReq text-red-500" data-i="${i}">Remove</button></td></tr>`).join('');$$('.removeReq').forEach(b=>b.onclick=()=>{state.requests.splice(Number(b.dataset.i),1);renderRequest()})}
function syncThemeButton(){const light=state.theme==='light';$('#themeLabel').textContent=light?'Dark Mode':'Light Mode';const icon=$('#themeIcon');if(icon)icon.innerHTML=light?'<svg viewBox="0 0 24 24"><path d="M21 12.8A8.5 8.5 0 1 1 11.2 3 7 7 0 0 0 21 12.8Z"/></svg>':'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/></svg>'}
