function bindAllocationActionButtons(){if(!isAdmin)return;$$('.adjustAllocationQty').forEach(btn=>btn.onclick=()=>openAllocationEditModal(Number(btn.dataset.index)));$$('.editAllocationLine').forEach(btn=>btn.onclick=()=>openAllocationEditModal(Number(btn.dataset.index)));$$('.deleteAllocationLine').forEach(btn=>btn.onclick=async()=>await deleteDeliveryAllocation(Number(btn.dataset.index)))}
