function openAllocationControlModal(index=null){if(!isAdmin)return;const modal=$('#allocationControlModal');if(!modal)return;const hasIndex=index!==null&&index!==undefined&&Number.isFinite(Number(index));if(Array.isArray(state.savedAllocationBaseline)&&!(state.delivery?.allocations||[]).length)enterAllocationCorrectionMode(hasIndex?Number(index):null);else if(hasIndex)enterAllocationCorrectionMode(Number(index));else renderAllocationTable();modal.classList.remove('hidden');modal.classList.add('flex');setTimeout(()=>{if(hasIndex){document.querySelector(`[data-allocation-card-index="${Number(index)}"]`)?.scrollIntoView({behavior:'smooth',block:'center'})}},80)}
