function activeDeliveryBranches(){return (state.delivery?.master?.branches||[]).filter(x=>x.active!==false)}
function activeDeliveryModels(){return [...new Map((state.delivery?.master?.models||[]).filter(x=>String(x.model||'').trim()).map(x=>[String(x.model||'').trim().toUpperCase(),String(x.model||'').trim()])).values()].sort((a,b)=>a.localeCompare(b))}
