async function loadDelivery(day,forceSaved=false){const batchMode=Array.isArray(state.savedAllocationBaseline),draftRows=batchMode?(state.delivery?.allocations||[]).map(x=>({...x})):null;const target=day||$('#deliveryDayFilter')?.value||'Whole Week';try{const d=await fetchJson('/api/delivery?day='+encodeURIComponent(target),{},'delivery');if(!d)return;if(batchMode){state.savedAllocationBaseline=(d.allocations||[]).map(x=>({...x}));d.allocations=draftRows||[]}if(state.deliveryBoardCleared&&!forceSaved&&!batchMode){d.schedule=[];d.allocations=[]}if(forceSaved)state.deliveryBoardCleared=false;state.delivery=d;renderDelivery()}catch(err){toast(err.message||'Unable to load Delivery Plan.',false)}}
