async function clearDeliveryData(target){
  if(target==='all'){
    if(!confirm('Clear the current working Delivery Board? The SAVED Weekly Truck Schedule and SAVED Allocation for the week will NOT be deleted. You can open them again from the Saved Delivery Plan bar.'))return;
    // v2.35: Clear Board is intentionally client-side only. Persisted weekly plan stays protected.
    if($('#scheduleImportFile'))$('#scheduleImportFile').value='';if($('#deliveryImportFile'))$('#deliveryImportFile').value='';
    if($('#scheduleImportWarnings')){$('#scheduleImportWarnings').textContent='';$('#scheduleImportWarnings').classList.add('hidden')}
    if($('#allocationWarnings')){$('#allocationWarnings').textContent='';$('#allocationWarnings').classList.add('hidden')}
    state.savedAllocationBaseline=null;state.deliveryBoardCleared=true;closeAllocationControlModal();closeAllocationEditModal();closeTripAssignmentModal();
    if(state.delivery){state.delivery.schedule=[];state.delivery.allocations=[]}
    resetScheduleEntry();markScheduleDirty(false);state.scheduleAreaFilter='All Areas';setScheduleCollapsed(false);setAllocationCollapsed(false);
    renderScheduleRows();renderAllocationTable();updateAllocationChrome();
    const bar=$('#savedDeliveryInputsBar');if(bar){bar.classList.remove('hidden');bar.classList.add('flex')}
    toast('Working board cleared. Saved Weekly Schedule + Allocation are protected — use View Weekly Schedule or View Allocation Import to open them again.');
    return;
  }
  const label='all saved allocation rows';
  if(!confirm(`Clear ${label}? This is a permanent saved-data action. Weekly Truck Schedule and masterlists will be preserved.`))return;
  const r=await fetch('/admin/delivery/clear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target})});const d=await r.json();if(!r.ok){toast(d.error||'Clear action failed.',false);return}
  state.savedAllocationBaseline=null;closeAllocationControlModal();closeAllocationEditModal();if(state.delivery)state.delivery.allocations=[];state.scheduleAreaFilter='All Areas';toast(d.message||'Saved allocations cleared.');await loadDelivery('Whole Week');
}
